window.ACAD = {"chapters": [{"key": "posture", "titre": "Posture & modèles", "sprint": "Sprint 1", "sections": [{"sid": "ent-sec-posture-1", "titre": "Posture entrepreneuriale", "lead": "Entreprendre, c'est décider dans l'incertitude. La posture compte plus que la méthode : traiter l'échec comme une information, agir à partir de ce qu'on a (effectuation) plutôt que d'attendre le plan parfait, et écrire une phrase-projet claire — pour qui, quel problème, quelle solution.", "qcm": [{"q": "Dans une posture entrepreneuriale saine, un échec est avant tout…", "choices": ["une sanction qui prouve qu'on n'est pas fait pour ça", "une information qui permet d'ajuster", "une raison d'abandonner le projet", "un hasard sans cause"], "answer": 1, "explain": "L'échec est traité comme une donnée exploitable : il indique quoi corriger, il ne juge pas la personne."}, {"q": "Qu'est-ce qu'une bonne « phrase-projet » ?", "choices": ["une liste de fonctionnalités du produit", "le montant qu'on veut gagner", "pour QUI, quel PROBLÈME, quelle SOLUTION", "le nom de la société et son logo"], "answer": 2, "explain": "Elle cadre le projet en une ligne autour du client, de son problème et de la solution — pas autour du produit."}, {"q": "L'approche « effectuation » consiste à…", "choices": ["attendre d'avoir le business plan parfait avant d'agir", "partir des moyens dont on dispose déjà et avancer par petits pas", "copier exactement un concurrent", "déléguer toutes les décisions à un expert"], "answer": 1, "explain": "On construit à partir de ses ressources actuelles (qui je connais, ce que je sais faire) plutôt que d'un plan figé."}]}, {"sid": "ent-sec-modeles-1", "titre": "Les 9 familles de modèles", "lead": "Le même effort peut construire zéro patrimoine… ou un actif qui se revend. La famille de modèle (négoce, services, production, marque D2C, abonnement, logiciel, plateforme, licence/franchise, audience) détermine la marge, le plafond de revenu et la valeur de revente. Un modèle classique se valorise en multiple d'EBITDA ; un modèle récurrent/scalable en multiple du chiffre d'affaires.", "qcm": [{"q": "Quel modèle a, en principe, le coût marginal le plus proche de zéro ?", "choices": ["le négoce (achat-revente)", "la prestation de services", "le logiciel", "la production artisanale"], "answer": 2, "explain": "Un logiciel se duplique sans coût supplémentaire notable : d'où sa scalabilité."}, {"q": "Pourquoi la prestation de services pure se revend-elle mal ?", "choices": ["parce qu'elle n'est pas rentable", "parce que la valeur dépend de la personne et le revenu plafonne aux heures vendues", "parce qu'elle est illégale en Belgique", "parce qu'elle ne génère jamais de marge"], "answer": 1, "explain": "Le revenu est borné par heures × tarif, et sans l'exploitant il reste peu à vendre."}, {"q": "Qu'apporte un modèle d'abonnement par rapport à une vente ponctuelle ?", "choices": ["un prix unitaire toujours plus élevé", "un chiffre d'affaires récurrent et prévisible qui augmente la valorisation", "la suppression de toute concurrence", "l'exonération de TVA"], "answer": 1, "explain": "La récurrence rend les revenus prévisibles, ce que les acheteurs valorisent fortement."}]}, {"sid": "ent-sec-modeles-2", "titre": "Le banc d'essai d'une idée", "lead": "Avant de se lancer, on passe l'idée au banc d'essai : marge par vente, seuil de rentabilité (le nombre de ventes qui permet de couvrir les charges ET de se payer), et potentiel de passage à l'échelle. Trois upgrades à chercher : plus de marge, de la récurrence, de la scalabilité.", "qcm": [{"q": "La marge par vente se calcule…", "choices": ["prix de vente − coût variable", "prix de vente + TVA", "chiffre d'affaires total", "prix de vente ÷ nombre de clients"], "answer": 0, "explain": "Marge unitaire = prix − coût variable ; c'est elle qui finance les charges fixes et le salaire."}, {"q": "Le seuil de rentabilité « qui te paie » correspond au nombre de ventes nécessaires pour couvrir…", "choices": ["uniquement les charges fixes", "charges fixes + ton salaire cible", "la TVA uniquement", "le coût d'acquisition client"], "answer": 1, "explain": "On vise le point où l'entreprise couvre ses charges ET te verse ton salaire, pas seulement l'équilibre comptable."}, {"q": "Un « upgrade » de modèle pertinent consiste par exemple à…", "choices": ["baisser le prix sans rien changer d'autre", "ajouter une part de revenu récurrent", "supprimer le service client", "augmenter les charges fixes"], "answer": 1, "explain": "Introduire de la récurrence (abonnement, maintenance) améliore la prévisibilité et la valeur."}]}]}, {"key": "vente", "titre": "Vente & premiers clients", "sprint": "Sprints 1-3", "sections": [{"sid": "ent-sec-vente-1", "titre": "Écouter : le Mom Test", "lead": "Une idée aimée n'est pas une idée achetée. Le Mom Test (Rob Fitzpatrick) : on interroge le passé réel du client (ce qu'il a déjà fait, payé, essayé), jamais ses bonnes intentions. On cherche des faits, pas des compliments.", "qcm": [{"q": "Selon le Mom Test, une bonne question d'interview porte sur…", "choices": ["ce que le client ferait hypothétiquement à l'avenir", "ce que le client a réellement fait et payé par le passé", "si le client aime votre idée", "le prix que le client accepterait en théorie"], "answer": 1, "explain": "Le passé réel est factuel ; les intentions futures sont des suppositions polies."}, {"q": "Un « compliment » recueilli en interview…", "choices": ["vaut une intention d'achat", "est une donnée fiable", "ne prouve rien sur l'achat futur", "garantit une vente"], "answer": 2, "explain": "« C'est une super idée » ne coûte rien à dire et n'engage personne à acheter."}, {"q": "Une véritable preuve de validation est…", "choices": ["un like sur les réseaux", "un acte : prévente, acompte, lettre d'intention, inscription", "un avis positif d'un proche", "un grand nombre de vues"], "answer": 1, "explain": "Seul un engagement concret (temps, argent, réputation) prouve l'intérêt réel."}]}, {"sid": "ent-sec-vente-2", "titre": "Prospecter & argumenter", "lead": "La vente commence dès le jour 1. On remplit un vrai pipeline (on ne l'attend pas), et on argumente avec SPIN (Situation, Problème, Implication, Need-payoff) et CAB (Caractéristique, Avantage, Bénéfice).", "qcm": [{"q": "Dans la méthode SPIN, le « I » (Implication) sert à…", "choices": ["décrire la société", "faire prendre conscience des conséquences du problème", "donner le prix", "clôturer la vente"], "answer": 1, "explain": "On amplifie le coût du problème pour que la solution devienne évidente."}, {"q": "Dans CAB, le « Bénéfice » est…", "choices": ["une propriété technique du produit", "ce que la caractéristique permet au client de gagner concrètement", "le prix de vente", "le nom commercial"], "answer": 1, "explain": "Le bénéfice traduit la caractéristique en gain réel pour CE client."}, {"q": "Un pipeline commercial sert à…", "choices": ["stocker les factures payées", "suivre les prospects et leur avancement vers l'achat", "calculer la TVA", "archiver les CGV"], "answer": 1, "explain": "C'est le tableau de bord des conversations commerciales en cours."}]}, {"sid": "ent-sec-vente-3", "titre": "Négocier & closer", "lead": "Le moment de vérité : demander de l'argent. On traite les objections, on négocie (Chris Voss : questions calibrées, ancrage, silence) et on close. Un chiffre d'affaires sans marge est une défaite déguisée.", "qcm": [{"q": "Pour Chris Voss, « ne jamais couper la poire en deux » signifie…", "choices": ["refuser toute discussion", "ne pas céder par réflexe à un compromis à 50 % qui détruit la valeur", "toujours baisser son prix", "ne jamais conclure"], "answer": 1, "explain": "Le compromis automatique fait perdre les deux parties ; mieux vaut comprendre le besoin réel."}, {"q": "Une « question calibrée » commence souvent par…", "choices": ["« Oui ou non ? »", "« Comment » ou « Quoi »", "« Est-ce que »", "« Pourquoi pas »"], "answer": 1, "explain": "Les questions ouvertes en « comment/quoi » font parler l'autre et révèlent ses contraintes."}, {"q": "Confondre chiffre d'affaires et marge est dangereux parce que…", "choices": ["le CA n'existe pas", "on peut vendre beaucoup et perdre de l'argent à chaque vente", "la marge est toujours égale au CA", "la TVA annule la marge"], "answer": 1, "explain": "Sans marge positive, plus on vend, plus on perd : le CA seul ne dit rien de la santé."}]}]}, {"key": "mkt", "titre": "Marketing & acquisition", "sprint": "Sprints 2-3", "sections": [{"sid": "ent-sec-mkt-1", "titre": "Le funnel & les canaux", "lead": "Le marketing ne remplace pas la vente : il la nourrit. Un seul funnel clair — attirer → intéresser → convertir — et des canaux choisis selon où se trouve le client. On surveille le coût d'acquisition (CAC) face à la valeur client (CLV).", "qcm": [{"q": "Le rôle du marketing par rapport à la vente est de…", "choices": ["la remplacer", "amener des conversations qualifiées à la vente", "fixer les prix de revient", "tenir la comptabilité"], "answer": 1, "explain": "Le marketing alimente le haut du funnel ; la vente transforme."}, {"q": "Le CAC désigne…", "choices": ["le coût d'acquisition d'un client", "le chiffre d'affaires client", "le capital de la société", "le crédit d'acquisition"], "answer": 0, "explain": "CAC = combien coûte, en moyenne, l'obtention d'un nouveau client."}, {"q": "Un ratio CLV/CAC sain est généralement…", "choices": ["inférieur à 1", "proche de 0", "nettement supérieur à 1 (souvent ≥ 3)", "toujours égal à 1"], "answer": 2, "explain": "La valeur d'un client doit dépasser largement son coût d'acquisition pour que le modèle tienne."}]}, {"sid": "ent-sec-mkt-2", "titre": "Contenu & tests à petit budget", "lead": "On teste avant de dépenser : landing page, maquette, petite annonce, avec un critère de succès défini à l'avance. L'IA produit le contenu ; toi, tu choisis l'angle et tu vends.", "qcm": [{"q": "Avant de lancer un test d'acquisition, il faut surtout…", "choices": ["dépenser le plus gros budget possible", "définir à l'avance un critère de succès", "supprimer le produit", "attendre six mois"], "answer": 1, "explain": "Un critère écrit AVANT évite de réinterpréter les résultats après coup."}, {"q": "Quel est le bon usage de l'IA pour le contenu marketing ?", "choices": ["elle décide seule de la stratégie", "elle produit des brouillons que l'entrepreneur oriente et valide", "elle remplace la vente", "elle garantit les ventes"], "answer": 1, "explain": "L'IA accélère la production ; le jugement sur l'angle et la vente reste humain."}, {"q": "Tester à petit budget permet surtout de…", "choices": ["éviter d'apprendre", "apprendre vite et pas cher avant d'engager de grosses sommes", "garantir le succès", "éviter de parler aux clients"], "answer": 1, "explain": "Le petit test réduit le risque avant un investissement plus lourd."}]}]}, {"key": "compta", "titre": "Compta & fiscalité (BE)", "sprint": "Sprints 3-4", "sections": [{"sid": "ent-sec-compta-1", "titre": "Lire ses chiffres", "lead": "Pas besoin d'être comptable : il faut savoir lire ses chiffres et ne pas se faire surprendre. On sépare les comptes dès le premier euro et on provisionne 35 à 40 % de chaque facture, car cotisations et impôts arrivent avec 1 à 2 ans de décalage.", "qcm": [{"q": "Quel réflexe adopter dès le premier euro encaissé ?", "choices": ["tout dépenser", "séparer compte pro et compte privé", "arrêter de facturer", "ignorer la TVA"], "answer": 1, "explain": "La séparation des comptes est la base d'un pilotage et d'une comptabilité saine."}, {"q": "Pourquoi provisionner 35-40 % de chaque facture ?", "choices": ["pour payer des dividendes", "parce que cotisations et impôts arrivent en décalé", "pour augmenter le prix", "c'est interdit"], "answer": 1, "explain": "Le décalage de 1 à 2 ans piège ceux qui ont déjà dépensé l'argent dû."}, {"q": "Le bilan et le compte de résultat diffèrent car…", "choices": ["ils sont identiques", "le bilan est une photo du patrimoine à un instant, le compte de résultat un film des produits et charges sur une période", "le bilan concerne la TVA uniquement", "le compte de résultat ne sert à rien"], "answer": 1, "explain": "Bilan = patrimoine à une date ; compte de résultat = performance sur une période."}]}, {"sid": "ent-sec-compta-2", "titre": "TVA & facturation", "lead": "Comprendre la TVA, émettre des factures conformes, respecter les échéances. L'IA peut préparer (OCR, catégorisation) ; toi ou le comptable vérifiez.", "qcm": [{"q": "Pour un assujetti, la TVA collectée sur les ventes est…", "choices": ["un revenu à garder", "une somme due à l'État (diminuée de la TVA déductible)", "un bénéfice net", "un capital social"], "answer": 1, "explain": "La TVA transite par l'entreprise : elle n'est pas un revenu, elle est reversée à l'État."}, {"q": "Un prix de 100 € HT avec une TVA de 21 % donne un TTC de…", "choices": ["100 €", "110 €", "121 €", "79 €"], "answer": 2, "explain": "100 × 1,21 = 121 € TTC."}, {"q": "Une facture conforme doit notamment comporter…", "choices": ["uniquement le montant", "les mentions légales (identité, numéro, date, TVA, détail)", "seulement un logo", "rien de particulier"], "answer": 1, "explain": "Les mentions obligatoires conditionnent la déductibilité et la conformité."}]}]}, {"key": "finance", "titre": "Finance & valorisation", "sprint": "Sprints 4-5", "sections": [{"sid": "ent-sec-finance-1", "titre": "Le plan financier", "lead": "Un plan financier n'est pas une prophétie : c'est un outil de pilotage. On le construit, on teste des scénarios, on identifie le besoin de financement et les bonnes sources.", "qcm": [{"q": "À quoi sert d'abord un plan financier ?", "choices": ["à prédire l'avenir avec certitude", "à piloter et tester des scénarios", "à décorer le business plan", "à remplacer la vente"], "answer": 1, "explain": "C'est un instrument de décision, révisable, pas une boule de cristal."}, {"q": "Le « besoin en fonds de roulement » apparaît surtout quand…", "choices": ["on paie ses fournisseurs après avoir été payé par ses clients", "on encaisse ses clients après avoir payé ses fournisseurs/stocks", "on n'a aucune charge", "le CA est nul"], "answer": 1, "explain": "Le décalage entre décaissements et encaissements crée un besoin de trésorerie à financer."}, {"q": "Tester un scénario « pessimiste » sert à…", "choices": ["se décourager", "connaître sa marge de sécurité et son point de rupture", "gonfler les prévisions", "éviter de vendre"], "answer": 1, "explain": "On vérifie la résistance du modèle si les ventes sont plus lentes que prévu."}]}, {"sid": "ent-sec-finance-2", "titre": "La valorisation (EBITDA × multiple)", "lead": "Combien vaut une entreprise ? La règle de base : EBITDA × multiple = valeur d'entreprise, le multiple allant d'environ 3× à 7×. Les curseurs qui font monter la valeur : revenus récurrents, clientèle diversifiée, équipe autonome, processus documentés.", "qcm": [{"q": "La formule de base de la valeur d'entreprise est…", "choices": ["chiffre d'affaires × nombre d'employés", "EBITDA × multiple", "actif − passif uniquement", "prix de revient × 2"], "answer": 1, "explain": "On part de la rentabilité (EBITDA) qu'on multiplie par un coefficient de marché."}, {"q": "Un EBITDA de 200 000 € avec un multiple de 4 donne une valeur d'entreprise de…", "choices": ["800 000 €", "200 000 €", "50 000 €", "2 000 000 €"], "answer": 0, "explain": "200 000 × 4 = 800 000 € de valeur d'entreprise (avant ajustement dettes/trésorerie)."}, {"q": "Quel facteur pousse le multiple vers le haut (vers 7×) ?", "choices": ["un seul client représentant 35 % du CA", "des revenus récurrents et des processus documentés", "une entreprise qui repose entièrement sur le dirigeant", "des revenus 100 % ponctuels"], "answer": 1, "explain": "Récurrence, diversification et autonomie réduisent le risque, donc augmentent le multiple."}]}]}, {"key": "pilotage", "titre": "Profitabilité & pilotage", "sprint": "Sprints 1,3,5", "sections": [{"sid": "ent-sec-pilotage-1", "titre": "Marge & tableau de bord", "lead": "Un tableau de bord simple vaut mieux qu'un reporting parfait jamais lu. On suit quelques indicateurs clés : marge, trésorerie, pipeline.", "qcm": [{"q": "Un bon tableau de bord d'entrepreneur est d'abord…", "choices": ["exhaustif et compliqué", "simple, suivi régulièrement, centré sur quelques indicateurs clés", "réservé au comptable", "annuel seulement"], "answer": 1, "explain": "Ce qui est simple et suivi bat ce qui est complet mais ignoré."}, {"q": "Parmi ces indicateurs, lequel surveille la survie à court terme ?", "choices": ["la trésorerie", "le nombre de pages du site", "le nombre d'abonnés", "la couleur du logo"], "answer": 0, "explain": "Une entreprise rentable peut mourir d'un manque de trésorerie."}, {"q": "La marge nette se distingue du chiffre d'affaires car elle…", "choices": ["est toujours plus grande que le CA", "est ce qui reste après toutes les charges", "ne dépend pas des coûts", "égale la TVA"], "answer": 1, "explain": "La marge nette mesure ce qui reste réellement, le CA mesure le volume facturé."}]}, {"sid": "ent-sec-pilotage-2", "titre": "Automatiser le back-office", "lead": "Le gain IA le plus concret : automatiser les tâches répétitives (devis, relances, catégorisation) pour gagner de la marge et du temps — sans jamais faire de l'IA le livrable vendu.", "qcm": [{"q": "Le bénéfice le plus concret de l'automatisation pour une TPE est…", "choices": ["impressionner les investisseurs", "libérer du temps et préserver la marge sur les tâches répétitives", "remplacer les clients", "supprimer la comptabilité légale"], "answer": 1, "explain": "Automatiser le répétitif rend du temps vendable et réduit les coûts."}, {"q": "Dans ce cours, l'IA est…", "choices": ["le produit à vendre", "un outil au service de l'entreprise, jamais le livrable", "interdite", "une obligation légale"], "answer": 1, "explain": "Principe directeur : l'IA n'est jamais le livrable ; elle sert l'entrepreneur."}, {"q": "Avant d'automatiser une tâche, il faut d'abord…", "choices": ["la comprendre et vérifier qu'elle a de la valeur", "la supprimer sans réfléchir", "la confier au client", "la rendre plus longue"], "answer": 0, "explain": "Automatiser une tâche inutile ne fait que produire plus vite quelque chose d'inutile."}]}]}, {"key": "juridique", "titre": "Juridique & création", "sprint": "Sprints 2-4", "sections": [{"sid": "ent-sec-juridique-1", "titre": "Formes & statuts", "lead": "Choisir sa forme (personne physique vs société) et comprendre ses obligations. En personne physique, le patrimoine privé est en principe exposé ; la société crée une personnalité juridique distincte.", "qcm": [{"q": "La différence majeure entre personne physique et société est…", "choices": ["aucune", "la société a une personnalité juridique distincte qui sépare les patrimoines", "la personne physique paie plus de TVA", "la société est gratuite"], "answer": 1, "explain": "La société protège davantage le patrimoine privé en le séparant de celui de l'entreprise."}, {"q": "Pour une décision juridique importante, le bon réflexe est…", "choices": ["suivre une réponse d'IA sans vérifier", "comprendre grâce à l'IA puis valider avec un professionnel", "ne jamais se renseigner", "copier un concurrent"], "answer": 1, "explain": "L'IA aide à comprendre ; la décision se valide avec un juriste/comptable."}, {"q": "Démarrer en personne physique peut convenir quand…", "choices": ["on veut tester une activité simplement et à moindre coût", "on a déjà des millions de CA", "on veut absolument lever des fonds", "jamais"], "answer": 0, "explain": "C'est souvent la rampe la plus simple pour tester, avant d'envisager une société."}]}, {"sid": "ent-sec-juridique-2", "titre": "Contrats & CGV", "lead": "Des conditions générales de vente (CGV) et des contrats clairs protègent l'entrepreneur : délais de paiement, responsabilités, propriété, résiliation.", "qcm": [{"q": "À quoi servent d'abord les CGV ?", "choices": ["à décorer le site", "à fixer les règles de la relation commerciale (paiement, responsabilités)", "à calculer l'impôt", "à remplacer la facture"], "answer": 1, "explain": "Les CGV cadrent la relation et réduisent les litiges."}, {"q": "Une clause de délai de paiement sert à…", "choices": ["offrir le produit", "encadrer quand et comment le client doit payer", "supprimer la TVA", "fixer le salaire"], "answer": 1, "explain": "Le délai de paiement protège la trésorerie et évite les impayés flous."}, {"q": "Signer un contrat sans le comprendre est risqué car…", "choices": ["ça fait gagner du temps", "on s'engage sur des obligations qu'on n'a pas mesurées", "les contrats n'engagent à rien", "c'est obligatoire"], "answer": 1, "explain": "Un engagement contractuel mal compris peut coûter très cher."}]}, {"sid": "ent-sec-juridique-3", "titre": "Reprendre plutôt que créer", "lead": "Créer cumule le risque de marché et d'exécution. Reprendre une PME rentable, c'est acheter une preuve de concept : clients, CA et équipes existent déjà. Une génération de dirigeants belges part à la retraite sans successeur.", "qcm": [{"q": "Reprendre une entreprise plutôt que la créer permet surtout…", "choices": ["d'éviter tout risque", "d'acheter une preuve de concept déjà rentable (clients, CA, équipe)", "de ne jamais payer", "d'éviter le banquier"], "answer": 1, "explain": "La reprise réduit le risque de marché : l'activité existe et tourne déjà."}, {"q": "Dans un dossier de reprise, l'interlocuteur clé à convaincre est souvent…", "choices": ["le facteur", "le banquier qui finance l'acquisition", "un influenceur", "le concurrent"], "answer": 1, "explain": "Le financement de la reprise se négocie d'abord avec la banque."}, {"q": "Un risque majeur à auditer avant de racheter une PME est…", "choices": ["la couleur des murs", "une forte dépendance à un seul client (ex. 35 % du CA)", "le nombre de pages du site", "la marque du café"], "answer": 1, "explain": "La concentration client menace la pérennité du chiffre d'affaires repris."}]}]}, {"key": "sepayer", "titre": "Se payer", "sprint": "Sprint 4", "sections": [{"sid": "ent-sec-sepayer-1", "titre": "Nom propre vs société & les 4 règles", "lead": "Ton salaire n'est pas « ce qui reste » : c'est un coût de l'entreprise, à prévoir dès le banc d'essai. Les 4 règles : séparer les comptes, provisionner 35-40 %, se payer un salaire même petit dès les premières ventes, et considérer son temps comme une ligne de coût.", "qcm": [{"q": "Dans une posture saine, ton salaire est…", "choices": ["ce qui reste à la fin s'il reste quelque chose", "une ligne de coût prévue dès le départ", "interdit la première année", "payé par le client directement"], "answer": 1, "explain": "Prévoir le salaire comme un coût évite le piège du « hobby coûteux »."}, {"q": "Laquelle NE fait PAS partie des 4 règles de « se payer » ?", "choices": ["séparer les comptes", "provisionner 35-40 %", "se payer un salaire même petit", "ne jamais facturer la TVA"], "answer": 3, "explain": "La TVA est une obligation distincte ; les 4 règles portent sur la discipline de rémunération."}, {"q": "Le statut d'indépendant complémentaire est souvent une bonne rampe car…", "choices": ["il interdit de vendre", "la couverture sociale est déjà assurée par l'emploi principal", "il supprime les impôts", "il est réservé aux sociétés"], "answer": 1, "explain": "La sécurité d'un emploi à côté permet de tester l'activité à moindre risque social."}]}]}, {"key": "final", "titre": "L'épreuve finale", "sprint": "Sprint 5", "sections": [{"sid": "ent-sec-final-1", "titre": "Plan d'entreprise & pitch", "lead": "L'épreuve finale : présenter son projet (création ou reprise) devant un jury de profs et de professionnels. On note les preuves, pas les promesses. Un pivot documenté peut valoir une excellente note. Le pitch est une vente.", "qcm": [{"q": "Devant le jury, ce qui compte le plus, ce sont…", "choices": ["les promesses et l'enthousiasme seuls", "les preuves (interviews, test, ventes, chiffres)", "la longueur de la présentation", "le nombre de slides"], "answer": 1, "explain": "Le jury évalue des preuves de traction, pas de simples intentions."}, {"q": "Un pivot bien mené pendant le parcours…", "choices": ["est toujours un échec", "peut être valorisé s'il est documenté et justifié par les apprentissages", "est interdit", "doit être caché au jury"], "answer": 1, "explain": "Changer de cap sur base de preuves est une compétence entrepreneuriale, pas une faute."}, {"q": "Le pitch final est fondamentalement…", "choices": ["un exercice de récitation", "une vente : convaincre avec une histoire et des preuves", "un rapport comptable", "une formalité sans enjeu"], "answer": 1, "explain": "On y applique tout ce qu'on a appris sur la vente et le storytelling."}]}]}], "exams": {"ent-exam-1": {"titre": "Examen 1 — Modèles, idée & validation", "qcm": [{"q": "Parmi ces propositions, laquelle ne fait PAS partie des 9 familles de modèles économiques étudiées ?", "choices": ["Le crowdfunding de don", "L'abonnement", "Le négoce (acheter pour revendre)", "La plateforme (mise en relation)"], "answer": 0, "explain": "Les 9 familles sont négoce, services, production, marque D2C, abonnement, logiciel, plateforme, licence/franchise et audience/freemium. Le crowdfunding est un mode de financement, pas un modèle économique."}, {"q": "Qu'est-ce qui distingue fondamentalement un modèle scalable d'un modèle classique ?", "choices": ["Le modèle scalable est toujours plus rentable dès la première année", "Dans un modèle scalable, servir un client supplémentaire coûte très peu, donc le chiffre d'affaires peut croître sans que les coûts suivent au même rythme", "Le modèle classique ne paie pas de TVA", "Le modèle scalable ne nécessite aucun client pour fonctionner"], "answer": 1, "explain": "La scalabilité, c'est la capacité à croître sans que les coûts augmentent proportionnellement : le coût marginal d'un client de plus est quasi nul (logiciel, plateforme), contrairement au service pur où chaque client mobilise du temps humain."}, {"q": "Un entrepreneur achète des vélos à un grossiste et les revend en boutique, sans les transformer. À quelle famille appartient son modèle ?", "choices": ["Production", "Licence/franchise", "Négoce", "Audience/freemium"], "answer": 2, "explain": "Le négoce consiste à acheter pour revendre sans transformation ; la valeur vient de la sélection, de la logistique et de la distribution, pas de la fabrication."}, {"q": "Un produit est acheté 60 € et revendu 100 €. Quel est le taux de marque (marge rapportée au prix de vente) ?", "choices": ["66,7 %", "166 %", "60 %", "40 %"], "answer": 3, "explain": "Marge unitaire = 100 − 60 = 40 €. Taux de marque = 40 / 100 = 40 %. Attention à ne pas le confondre avec le taux de marge sur coût (40/60 = 66,7 %)."}, {"q": "Une activité supporte 30 000 € de charges fixes par an et dégage une marge sur coûts variables de 40 % du chiffre d'affaires. Quel est son seuil de rentabilité (chiffre d'affaires) ?", "choices": ["75 000 €", "45 000 €", "12 000 €", "120 000 €"], "answer": 0, "explain": "Seuil = charges fixes / taux de marge sur coûts variables = 30 000 / 0,40 = 75 000 €. En dessous de ce CA, l'activité perd de l'argent."}, {"q": "Selon le Mom Test de Rob Fitzpatrick, quelle question est la plus fiable lors d'un entretien client ?", "choices": ["Est-ce que vous achèteriez mon produit si je le lançais ?", "Racontez-moi la dernière fois que vous avez rencontré ce problème : qu'avez-vous fait concrètement ?", "Trouvez-vous que c'est une bonne idée ?", "Combien seriez-vous prêt à payer pour ça ?"], "answer": 1, "explain": "Le Mom Test consiste à parler du passé réel et des comportements concrets du client, pas de ses intentions ni d'opinions sur votre idée, qui sont des réponses de complaisance."}, {"q": "Un prospect vous dit : « Super idée, ça peut vraiment marcher ! ». Comment interpréter ce signal ?", "choices": ["C'est une validation forte : l'idée est prouvée", "Cela équivaut à une commande", "C'est un compliment poli, pas une preuve d'intention d'achat ; il faut chercher un engagement concret", "Cela permet de fixer le prix du produit"], "answer": 2, "explain": "Un compliment n'est pas une intention d'achat. La vraie validation passe par un engagement concret : un acompte, une précommande, un rendez-vous pris, du temps ou de l'argent engagé."}, {"q": "Dans l'analyse TAM / SAM / SOM, que représente le SAM ?", "choices": ["Le marché total théorique, tous clients confondus", "Le montant des subventions accessibles", "La part de marché que vous comptez capter à court terme", "La part du marché total que votre offre peut réellement adresser compte tenu de votre modèle et de votre géographie"], "answer": 3, "explain": "TAM = marché total, SAM = marché adressable (ce que votre offre peut servir), SOM = marché réellement captable à court terme. Le SAM resserre le TAM selon vos contraintes réelles."}, {"q": "Le TAM compte 1 000 000 de clients potentiels. Votre SAM représente 20 % du TAM, et votre SOM 10 % du SAM. Combien de clients vise le SOM ?", "choices": ["20 000 clients", "100 000 clients", "200 000 clients", "2 000 clients"], "answer": 0, "explain": "SAM = 1 000 000 × 20 % = 200 000. SOM = 200 000 × 10 % = 20 000 clients. Le SOM est la cible réaliste à court terme."}, {"q": "À quoi sert un persona dans la validation d'une idée ?", "choices": ["À inventer un client idéal qui n'existe pas pour rassurer l'investisseur", "À décrire précisément un profil de client cible réel (situation, problème, comportement) pour cibler recherche et offre", "À fixer le prix de vente", "À calculer la TVA"], "answer": 1, "explain": "Le persona synthétise un profil de client réel pour orienter les entretiens, le message et l'offre. Il doit reposer sur des observations terrain, pas sur une projection fantasmée."}, {"q": "Pourquoi faut-il définir un critère de succès AVANT de lancer un test de validation ?", "choices": ["Pour pouvoir publier le test sur les réseaux sociaux", "Parce que la loi belge l'impose", "Parce que sans seuil fixé à l'avance, on interprétera n'importe quel résultat comme un succès (biais de confirmation)", "Parce que cela augmente automatiquement le taux de conversion"], "answer": 2, "explain": "Fixer à l'avance (ex. « au moins 15 précommandes sur 100 visiteurs ») empêche de se raconter des histoires après coup et rend le test honnête et décisif."}, {"q": "Quel est le principal avantage économique d'un modèle par abonnement ?", "choices": ["Il supprime toute concurrence", "Il ne nécessite jamais de rétention client", "Il exonère de TVA", "Il génère des revenus récurrents et prévisibles, qui facilitent la gestion et augmentent la valeur de l'entreprise"], "answer": 3, "explain": "L'abonnement crée de la récurrence : revenus prévisibles, meilleure visibilité de trésorerie et valorisation plus élevée, à condition de bien gérer la rétention (le churn)."}, {"q": "Une marque D2C (direct-to-consumer) se caractérise par :", "choices": ["La vente directe au consommateur final, en maîtrisant sa marque, sa relation client et ses marges sans intermédiaire", "La vente exclusivement via des grossistes", "L'absence totale de produit physique", "L'interdiction de faire de la publicité"], "answer": 0, "explain": "Le D2C supprime les intermédiaires : la marque contrôle sa relation client, ses données et capte la marge habituellement laissée au distributeur, en échange d'un effort marketing accru."}, {"q": "Dans un modèle de plateforme, d'où vient principalement la valeur ?", "choices": ["De la fabrication des produits vendus", "De la mise en relation efficace entre deux groupes (offre et demande) et de l'effet de réseau", "De la détention d'un brevet unique", "De l'absence d'utilisateurs"], "answer": 1, "explain": "Une plateforme crée de la valeur en connectant offre et demande ; sa force vient de l'effet de réseau : plus il y a d'utilisateurs d'un côté, plus elle attire l'autre côté."}, {"q": "Pourquoi un modèle logiciel (SaaS) est-il souvent très scalable ?", "choices": ["Parce qu'il n'a aucun coût de développement", "Parce qu'il est exonéré de charges sociales", "Parce qu'une fois le logiciel développé, servir un client de plus coûte presque rien", "Parce qu'il ne nécessite jamais de support client"], "answer": 2, "explain": "Le coût marginal d'un utilisateur supplémentaire est quasi nul une fois le produit développé ; les revenus peuvent croître bien plus vite que les coûts."}, {"q": "Le modèle licence / franchise consiste essentiellement à :", "choices": ["Vendre ses produits à perte", "Racheter ses concurrents", "Distribuer gratuitement son savoir-faire", "Monétiser un concept, une marque ou un savoir-faire éprouvés en les faisant exploiter par d'autres contre redevance"], "answer": 3, "explain": "La licence/franchise vend le droit d'exploiter un concept, une marque ou un savoir-faire validés ; le franchiseur touche des redevances et croît via le capital des franchisés."}, {"q": "Dans un modèle audience / freemium, comment se fait principalement la monétisation ?", "choices": ["En attirant une large audience avec une offre gratuite, puis en monétisant une minorité (version payante) et/ou l'audience (publicité)", "En faisant payer tous les utilisateurs dès l'inscription", "En interdisant l'accès gratuit", "En vendant uniquement aux concurrents"], "answer": 0, "explain": "Le freemium capte une large base gratuite, puis convertit une petite part en clients payants ou monétise l'audience. Tout dépend du taux de conversion du gratuit vers le payant."}, {"q": "Un modèle de production se distingue du négoce parce que :", "choices": ["Il ne vend jamais ses produits", "Il transforme des matières ou composants en un produit fini, ajoutant de la valeur par la fabrication", "Il n'achète aucune matière première", "Il est toujours exonéré de TVA"], "answer": 1, "explain": "La production crée de la valeur par la transformation (fabrication), là où le négoce se contente d'acheter pour revendre. La production exige souvent plus de capital et d'outillage."}, {"q": "Quelle est la principale limite d'un pur modèle de services (prestation facturée au temps) ?", "choices": ["Il ne génère jamais de chiffre d'affaires", "Il est illégal en Belgique", "Il est peu scalable : le revenu est plafonné par le temps disponible, et l'entreprise se revend mal", "Il ne permet pas de facturer la TVA"], "answer": 2, "explain": "Le service pur est borné par le temps humain : difficile à faire croître sans embaucher, et très dépendant des personnes, donc peu scalable et difficile à revendre."}, {"q": "Au banc d'essai d'une idée, vous constatez une marge très faible et non améliorable. Que conclure ?", "choices": ["Il faut lancer immédiatement, le volume compensera", "Il faut augmenter les charges fixes", "La marge n'a aucune importance pour une startup", "Une marge structurellement faible est un signal d'alerte : chaque vente rapporte peu, et la moindre difficulté rend l'activité déficitaire"], "answer": 3, "explain": "Une marge faible laisse peu de coussin pour absorber les imprévus, financer la croissance ou se payer. Au banc d'essai, marge, seuil de rentabilité et scalabilité sont les trois filtres de base."}, {"q": "Deux projets ont la même marge. L'un double son CA en embauchant proportionnellement, l'autre double son CA quasi sans coûts supplémentaires. Lequel est scalable ?", "choices": ["Le second", "Le premier", "Les deux à l'identique", "Aucun des deux"], "answer": 0, "explain": "La scalabilité, c'est croître sans que les coûts suivent proportionnellement. Le second projet voit ses marges s'améliorer avec la taille ; le premier reste plafonné par ses coûts."}, {"q": "Une prestation est vendue 500 €. Son coût variable est de 150 €. Quel est le taux de marge sur le prix de vente ?", "choices": ["30 %", "70 %", "233 %", "150 %"], "answer": 1, "explain": "Marge = 500 − 150 = 350 €. Taux sur prix de vente = 350 / 500 = 70 %. C'est la part de chaque euro vendu qui reste disponible pour couvrir les charges fixes et dégager du profit."}, {"q": "Les charges fixes s'élèvent à 18 000 € par an et la marge est de 30 € par unité vendue. Combien d'unités faut-il vendre pour atteindre le seuil de rentabilité ?", "choices": ["300 unités", "540 unités", "600 unités", "6 000 unités"], "answer": 2, "explain": "Seuil en unités = charges fixes / marge unitaire = 18 000 / 30 = 600 unités. En dessous, l'activité est déficitaire."}, {"q": "Selon le Mom Test, laquelle de ces questions est la plus trompeuse à poser ?", "choices": ["Combien de temps vous a pris cette tâche la semaine dernière ?", "Que faites-vous aujourd'hui pour résoudre ce problème ?", "Quelle solution avez-vous déjà payée pour ça ?", "Est-ce que vous utiliseriez une appli qui ferait ça pour vous ?"], "answer": 3, "explain": "« Est-ce que vous utiliseriez... » porte sur une intention future hypothétique : le client dit oui pour faire plaisir. Les autres questions portent sur des faits et comportements passés, bien plus fiables."}, {"q": "Quel est l'objectif des entretiens clients en phase de validation ?", "choices": ["Comprendre en profondeur le problème, le contexte et les comportements réels du client, pas vendre ni valider son ego", "Convaincre le client d'acheter immédiatement", "Faire signer un contrat de distribution", "Recruter des investisseurs"], "answer": 0, "explain": "En validation, on écoute et on apprend : on cherche la vérité du problème vécu, pas à vendre. Vendre trop tôt pollue l'information recueillie."}, {"q": "Pourquoi un entretien terrain bien mené vaut-il souvent mieux qu'un sondage en ligne auto-déclaratif ?", "choices": ["Parce qu'il touche plus de monde", "Parce qu'il permet de creuser le passé réel, de relancer et de détecter les contradictions entre ce que les gens disent et ce qu'ils font", "Parce qu'il est gratuit et sans effort", "Parce que les sondages sont interdits en Belgique"], "answer": 1, "explain": "L'entretien permet de relancer, de demander des exemples concrets du passé et de repérer l'écart entre le discours et le comportement, là où un sondage ne recueille que des intentions déclarées."}, {"q": "Votre SAM compte 5 000 entreprises. Vous visez une part de 4 % avec un prix moyen de 2 000 € par an et par client. Quel chiffre d'affaires annuel (SOM en valeur) cela représente-t-il ?", "choices": ["40 000 €", "200 000 €", "400 000 €", "1 000 000 €"], "answer": 2, "explain": "Clients visés = 5 000 × 4 % = 200. CA = 200 × 2 000 = 400 000 €. Traduire le SOM en euros permet de tester si l'ambition est atteignable et suffisante."}, {"q": "Lequel de ces projets illustre le mieux un modèle scalable ?", "choices": ["Un consultant qui facture ses journées de conseil", "Un artisan qui fabrique des meubles sur mesure", "Un salon de coiffure unique", "Une application en ligne vendue par abonnement à des milliers d'utilisateurs"], "answer": 3, "explain": "L'application par abonnement peut servir des milliers d'utilisateurs supplémentaires à coût marginal quasi nul ; les trois autres sont bornés par le temps humain ou par la capacité d'un lieu."}, {"q": "Quelle est la différence entre marge brute et marge nette ?", "choices": ["La marge brute se calcule après les seuls coûts directs/variables ; la marge nette se calcule après TOUTES les charges (fixes, financières, impôts)", "Il n'y en a aucune", "La marge nette est toujours plus élevée que la marge brute", "La marge brute inclut les impôts, pas la marge nette"], "answer": 0, "explain": "La marge brute retranche les coûts directement liés à la vente ; la marge nette retranche en plus toutes les autres charges. La nette est donc inférieure à la brute."}, {"q": "Les charges fixes annuelles sont de 50 000 € et le taux de marge sur coûts variables est de 25 %. Quel est le chiffre d'affaires au point mort ?", "choices": ["12 500 €", "200 000 €", "125 000 €", "62 500 €"], "answer": 1, "explain": "Point mort = charges fixes / taux de marge = 50 000 / 0,25 = 200 000 €. Un taux de marge faible exige un chiffre d'affaires d'autant plus élevé pour couvrir les frais fixes."}]}, "ent-exam-2": {"titre": "Examen 2 — Vente & marketing", "qcm": [{"q": "Qu'est-ce que le pipeline (ou pipe) commercial ?", "choices": ["L'ensemble des opportunités de vente réparties par étape, de la prise de contact jusqu'au closing", "La liste des factures impayées", "Le budget publicitaire mensuel", "Le stock de marchandises disponibles"], "answer": 0, "explain": "Le pipeline représente les affaires en cours, classées par étape d'avancement. Il permet de prévoir le chiffre d'affaires et de savoir où relancer pour alimenter la vente."}, {"q": "Dans la méthode SPIN, que recouvrent les quatre lettres ?", "choices": ["Stock, Prix, Idée, Négoce", "Situation, Problème, Implication, Need-payoff (bénéfice de la solution)", "Stratégie, Produit, Image, Notoriété", "Service, Paiement, Intérêt, Nom"], "answer": 1, "explain": "SPIN structure l'entretien : questions de Situation, puis de Problème, puis d'Implication (conséquences du problème), puis de Need-payoff (valeur de le résoudre)."}, {"q": "À quoi servent les questions d'Implication dans SPIN ?", "choices": ["À présenter le prix tout de suite", "À conclure la vente immédiatement", "À faire prendre conscience au client des conséquences et du coût de son problème s'il ne le résout pas", "À parler des caractéristiques techniques du produit"], "answer": 2, "explain": "Les questions d'Implication amplifient la douleur : elles amènent le client à mesurer lui-même ce que lui coûte son problème, ce qui crée l'urgence d'agir."}, {"q": "Que signifie la méthode CAB appliquée à un argumentaire de vente ?", "choices": ["Coût, Achat, Budget", "Contrat, Acompte, Bon de commande", "Client, Affaire, Besoin", "Caractéristique, Avantage, Bénéfice"], "answer": 3, "explain": "CAB relie une caractéristique du produit à l'avantage qu'elle procure, puis au bénéfice concret pour CE client. On vend le bénéfice, pas la caractéristique."}, {"q": "Dans CAB, quelle phrase exprime un BÉNÉFICE (et non un simple avantage) ?", "choices": ["Vous ne perdrez plus jamais une soirée de travail à cause d'une panne, et vous dormirez tranquille", "Il sauvegarde toutes les 5 minutes", "Ce logiciel possède une sauvegarde automatique", "Il est écrit en langage moderne"], "answer": 0, "explain": "Le bénéfice traduit l'avantage en gain concret et personnel pour le client (tranquillité, temps gagné). La caractéristique décrit le produit, l'avantage ce qu'il permet, le bénéfice ce que le client y gagne vraiment."}, {"q": "Face à l'objection « c'est trop cher », quelle est la meilleure première réaction ?", "choices": ["Baisser immédiatement le prix", "Chercher à comprendre : trop cher par rapport à quoi, à quel budget, à quelle valeur perçue ?", "Mettre fin à l'entretien", "Dire au client qu'il a tort"], "answer": 1, "explain": "Une objection est une demande d'information. On questionne pour comprendre ce qu'elle recouvre réellement (référence, budget, valeur) avant de répondre, plutôt que de céder sur le prix."}, {"q": "Qu'est-ce que le closing dans un processus de vente ?", "choices": ["Le fait de clôturer le dossier sans vendre", "La fermeture annuelle des comptes", "L'étape où l'on amène explicitement le client à prendre la décision et à s'engager", "L'envoi de la facture TVA"], "answer": 2, "explain": "Le closing est le moment où l'on demande clairement l'engagement. Sans demande explicite de décision, beaucoup de ventes bien menées restent inabouties."}, {"q": "Selon Chris Voss, qu'est-ce qu'une question calibrée ?", "choices": ["Une question fermée qui appelle oui ou non", "Une question piège pour déstabiliser", "Une question sur le prix uniquement", "Une question ouverte en « comment » ou « quoi » qui fait travailler l'autre et lui donne l'illusion du contrôle"], "answer": 3, "explain": "Les questions calibrées (« Comment suis-je censé faire ça ? ») engagent l'autre à résoudre votre problème sans confrontation, tout en lui laissant le sentiment de maîtriser l'échange."}, {"q": "Pourquoi Chris Voss conseille-t-il de ne JAMAIS « couper la poire en deux » ?", "choices": ["Parce que le compromis mécanique mène souvent à un mauvais accord pour les deux parties ; mieux vaut comprendre le vrai besoin de l'autre", "Parce que c'est interdit par la loi", "Parce qu'il faut toujours imposer son prix de départ", "Parce que la négociation doit être évitée"], "answer": 0, "explain": "Couper la poire en deux donne un accord médiocre que personne ne défend vraiment. Voss préfère creuser les intérêts réels pour trouver une solution qui crée davantage de valeur."}, {"q": "Quel rôle joue le silence dans une négociation selon Chris Voss ?", "choices": ["Il faut l'éviter car il met mal à l'aise", "Se taire après une question ou une proposition pousse l'autre à parler, à se dévoiler, parfois à concéder", "Le silence signifie toujours un refus", "Le silence doit durer au moins dix minutes"], "answer": 1, "explain": "Le silence est un outil : après une question calibrée ou une offre, se taire crée une tension que l'interlocuteur comble souvent en livrant de l'information ou en bougeant sa position."}, {"q": "Qu'est-ce que l'ancrage en négociation ?", "choices": ["Signer sans discuter", "Refuser de négocier", "Fixer un point de référence (souvent le premier chiffre avancé) qui oriente ensuite toute la discussion", "Payer un acompte"], "answer": 2, "explain": "L'ancrage pose un repère psychologique : le premier chiffre énoncé tire la négociation vers lui. D'où l'importance de maîtriser qui ancre et à quel niveau."}, {"q": "Quelle est la différence essentielle entre chiffre d'affaires et marge ?", "choices": ["Aucune, ce sont des synonymes", "Le chiffre d'affaires se calcule après impôts", "La marge est toujours supérieure au chiffre d'affaires", "Le chiffre d'affaires est le total facturé ; la marge est ce qui reste après avoir déduit les coûts. On ne vit pas du CA, on vit de la marge"], "answer": 3, "explain": "Un gros chiffre d'affaires à marge nulle ne nourrit personne. C'est la marge, et au final la trésorerie, qui compte : vendre plus n'a de sens que si chaque vente rapporte."}, {"q": "Une entreprise vend pour 10 000 € de marchandises qui lui ont coûté 7 000 € à l'achat. Quelle est sa marge brute, en euros et en pourcentage du CA ?", "choices": ["3 000 € soit 30 %", "7 000 € soit 70 %", "3 000 € soit 43 %", "10 000 € soit 100 %"], "answer": 0, "explain": "Marge = 10 000 − 7 000 = 3 000 €. Taux sur CA = 3 000 / 10 000 = 30 %. C'est cette marge, et non le CA, qui doit couvrir toutes les autres charges."}, {"q": "Le funnel « attirer → intéresser → convertir » décrit :", "choices": ["Le processus de fabrication d'un produit", "Le parcours par lequel un inconnu devient prospect intéressé puis client, à chaque étape une déperdition", "Le calcul de la TVA", "L'organigramme de l'entreprise"], "answer": 1, "explain": "Le funnel (entonnoir) décrit la conversion progressive : on attire une audience, on en intéresse une partie, on en convertit une fraction en clients. À chaque étape, on perd du monde."}, {"q": "Que mesure le CAC (coût d'acquisition client) ?", "choices": ["Le prix de vente moyen d'un produit", "Le montant total des salaires", "Combien il coûte, en moyenne, pour acquérir un nouveau client (marketing + vente / nombre de clients gagnés)", "La TVA sur les ventes"], "answer": 2, "explain": "Le CAC rapporte les dépenses d'acquisition au nombre de clients gagnés. Il doit rester nettement inférieur à ce qu'un client rapporte sur sa durée de vie (la CLV)."}, {"q": "Vous dépensez 5 000 € en marketing et vente sur un mois et gagnez 50 nouveaux clients. Quel est votre CAC ?", "choices": ["50 €", "500 €", "250 €", "100 €"], "answer": 3, "explain": "CAC = 5 000 / 50 = 100 € par client. Il faut ensuite le comparer à la valeur que ce client génère pour savoir si l'acquisition est rentable."}, {"q": "Que représente la CLV (customer lifetime value) ?", "choices": ["La valeur totale (marge) qu'un client rapporte sur toute la durée de sa relation avec l'entreprise", "Le coût de fabrication d'un produit", "Le capital social de la société", "Le nombre de clients perdus par an"], "answer": 0, "explain": "La CLV estime la marge cumulée d'un client sur sa durée de vie. Comparée au CAC, elle dit si le modèle d'acquisition est soutenable."}, {"q": "Un client reste en moyenne 3 ans et génère 200 € de marge par an. Quelle est sa CLV (hors actualisation) ?", "choices": ["200 €", "600 €", "400 €", "66 €"], "answer": 1, "explain": "CLV = 200 € × 3 ans = 600 €. Cette valeur sert de plafond raisonnable au montant qu'on peut investir pour acquérir un tel client."}, {"q": "Avec une CLV de 600 € et un CAC de 100 €, quel est le ratio CLV/CAC, et est-il sain ?", "choices": ["0,17 — insuffisant", "1 — à l'équilibre", "6 — sain (nettement supérieur à 3)", "600 — aberrant"], "answer": 2, "explain": "Ratio = 600 / 100 = 6. Un ratio CLV/CAC supérieur à 3 est généralement considéré comme sain : chaque euro d'acquisition rapporte plusieurs euros de marge."}, {"q": "Pourquoi tester une annonce avec un petit budget avant de dépenser gros ?", "choices": ["Parce que c'est obligatoire fiscalement", "Parce qu'un petit budget garantit plus de ventes", "Parce que les grosses campagnes sont interdites aux indépendants", "Pour mesurer à faible coût ce qui accroche réellement (message, cible, visuel) avant d'investir, et éviter de brûler le budget sur une mauvaise hypothèse"], "answer": 3, "explain": "Un test à petit budget transforme une intuition en donnée : on compare des variantes, on garde ce qui convertit, puis on met l'argent là où ça marche."}, {"q": "Dans une logique de contenu au service de la vente, quel est le bon réflexe ?", "choices": ["Produire du contenu utile qui attire la cible et nourrit la confiance, en l'orientant vers une étape du funnel", "Publier uniquement des promotions permanentes", "Ne jamais mentionner son offre", "Copier les publications des concurrents"], "answer": 0, "explain": "Le contenu attire et crédibilise, mais il doit servir la vente : chaque publication a un rôle dans le funnel (attirer, intéresser, convertir), sinon c'est de l'activité sans résultat."}, {"q": "Une page reçoit 2 000 visiteurs et affiche un taux de conversion de 3 %. Combien de clients cela génère-t-il ?", "choices": ["6 clients", "60 clients", "30 clients", "600 clients"], "answer": 1, "explain": "Clients = 2 000 × 3 % = 60. Améliorer le taux de conversion a souvent plus d'effet, et moins cher, que d'acheter davantage de trafic."}, {"q": "Vous dépensez 800 € de publicité et récoltez 40 leads. Quel est le coût par lead ?", "choices": ["8 €", "32 €", "20 €", "200 €"], "answer": 2, "explain": "Coût par lead = 800 / 40 = 20 €. Ce coût, combiné au taux de transformation lead→client, permet de remonter au coût d'acquisition réel."}, {"q": "À quoi servent les questions de Need-payoff (N de SPIN) ?", "choices": ["À conclure sans argumenter", "À annoncer le prix", "À décrire les caractéristiques techniques", "À faire dire au client lui-même la valeur qu'il tirerait de la solution"], "answer": 3, "explain": "Les questions de Need-payoff amènent le client à verbaliser le gain (« Si vous régliez ça, qu'est-ce que ça changerait ? »). C'est lui qui se vend la solution, bien plus efficace qu'un argumentaire du vendeur."}, {"q": "Un client soulève une objection sincère sur un point précis. Quelle est l'erreur à éviter ?", "choices": ["La balayer ou se mettre sur la défensive au lieu de la traiter", "La reformuler pour vérifier qu'on l'a comprise", "L'écouter jusqu'au bout", "Y répondre par un bénéfice concret"], "answer": 0, "explain": "Balayer ou contredire frontalement une objection braque le client. On écoute, on reformule, on comprend, puis on répond par la valeur : l'objection devient une occasion d'avancer."}, {"q": "Dans une négociation, pourquoi le choix de la première offre (ancre) est-il stratégique ?", "choices": ["Parce qu'elle n'a aucun effet sur la suite", "Parce que le premier chiffre pose la référence autour de laquelle les deux parties ajusteront ensuite leurs positions", "Parce qu'elle doit toujours être la plus basse possible", "Parce qu'elle fixe le taux de TVA"], "answer": 1, "explain": "La première offre ancre la discussion : bien placée et justifiée, elle tire l'accord final vers elle. Mal placée, elle peut aussi vous enfermer, d'où l'importance de la préparer."}, {"q": "Quelle affirmation résume le mieux le rapport entre marketing et vente ?", "choices": ["Le marketing remplace la vente", "La vente est inutile si l'on fait du marketing", "Le marketing prépare et facilite la vente ; il attire et chauffe les prospects, mais c'est la vente qui conclut", "Les deux sont sans rapport"], "answer": 2, "explain": "Le marketing alimente le haut du funnel et crédibilise, la vente transforme. Ils se servent l'un l'autre, mais la vente reste la matière reine : sans conclusion, pas de chiffre d'affaires."}, {"q": "Sur 20 propositions commerciales envoyées, 5 sont signées. Quel est le taux de closing ?", "choices": ["4 %", "15 %", "40 %", "25 %"], "answer": 3, "explain": "Taux de closing = 5 / 20 = 25 %. Connaître ce taux permet de calculer combien de propositions il faut faire pour atteindre un objectif de ventes donné."}, {"q": "Lequel de ces éléments est un signal d'achat pendant un entretien de vente ?", "choices": ["Le client demande les délais de livraison et les modalités de paiement", "Le client regarde sa montre et croise les bras", "Le client répète qu'il doit réfléchir sans poser de question", "Le client change de sujet"], "answer": 0, "explain": "Quand le client se projette dans l'après-achat (délais, paiement, mise en place), c'est un signal d'achat : le moment de proposer de conclure plutôt que de continuer à argumenter."}, {"q": "Pourquoi qualifier un prospect avant d'investir du temps dans la vente ?", "choices": ["Pour lui faire perdre du temps", "Pour vérifier qu'il a un besoin réel, un budget et un pouvoir de décision, et concentrer l'effort sur les affaires réellement gagnables", "Parce que la loi l'exige", "Pour fixer la TVA applicable"], "answer": 1, "explain": "Qualifier (besoin, budget, décideur, échéance) évite de dépenser son énergie sur des affaires sans issue. Un bon pipeline est fait d'opportunités qualifiées, pas d'un empilement de contacts tièdes."}]}, "ent-exam-3": {"titre": "Examen 3 — Les chiffres : compta, fiscalité, finance, valorisation, juridique", "qcm": [{"q": "Quelle est la différence entre le bilan et le compte de résultat ?", "choices": ["Le bilan est une photo du patrimoine (actif/passif) à un instant donné ; le compte de résultat retrace les produits et charges sur une période", "Ce sont deux noms pour le même document", "Le bilan mesure le chiffre d'affaires mensuel", "Le compte de résultat liste les dettes bancaires uniquement"], "answer": 0, "explain": "Le bilan est statique (ce que l'entreprise possède et doit à une date) ; le compte de résultat est dynamique (ce qu'elle a gagné et dépensé sur l'exercice). Les deux se complètent."}, {"q": "Quel est le taux de TVA standard en Belgique ?", "choices": ["6 %", "21 %", "20 %", "12 %"], "answer": 1, "explain": "Le taux normal de TVA en Belgique est de 21 %. Il existe des taux réduits (6 % et 12 %) pour certains biens et services, mais 21 % est le taux par défaut."}, {"q": "Vous émettez une facture de 1 000 € hors TVA, au taux de 21 %. Quel est le montant TTC à encaisser ?", "choices": ["1 021 €", "1 060 €", "1 210 €", "1 021,0 €"], "answer": 2, "explain": "TVA = 1 000 × 21 % = 210 €. TTC = 1 000 + 210 = 1 210 €. Cette TVA de 210 € n'est pas un revenu : elle est collectée pour l'État et devra être reversée."}, {"q": "Parmi ces mentions, laquelle est obligatoire sur une facture belge ?", "choices": ["La couleur préférée du client", "Le montant du loyer de l'entreprise", "Le salaire du gérant", "Le numéro de TVA (BE...) de l'émetteur, la date, un numéro de facture et le détail HT/TVA/TTC"], "answer": 3, "explain": "Une facture conforme mentionne notamment les coordonnées et numéros de TVA, une numérotation, la date, la description, le montant hors TVA, le taux et le montant de TVA, et le total TTC."}, {"q": "Pourquoi conseille-t-on à un indépendant de provisionner 35 à 40 % de chaque facture encaissée ?", "choices": ["Pour mettre de côté de quoi couvrir les cotisations sociales et l'impôt à venir, et ne pas être pris au dépourvu", "Pour payer son loyer", "Parce que c'est une obligation légale immédiate", "Pour augmenter son chiffre d'affaires"], "answer": 0, "explain": "L'argent encaissé n'est pas tout à vous : cotisations sociales et impôts tomberont plus tard. Provisionner 35-40 % sur un compte dédié évite la catastrophe de trésorerie quand l'avis arrive."}, {"q": "Vous encaissez 10 000 € de marge sur un projet et appliquez une provision de 40 % pour cotisations et impôts. Combien mettez-vous de côté ?", "choices": ["400 €", "4 000 €", "6 000 €", "3 500 €"], "answer": 1, "explain": "Provision = 10 000 × 40 % = 4 000 €. Il ne reste réellement disponible que 6 000 €. Confondre encaissement et revenu net est l'erreur classique du débutant."}, {"q": "À quoi sert un plan financier avant de lancer son activité ?", "choices": ["À faire joli pour la banque uniquement", "À fixer le taux de TVA", "À chiffrer les besoins de financement, les recettes et dépenses prévisionnelles et à vérifier la viabilité et la trésorerie du projet", "À calculer les congés payés"], "answer": 2, "explain": "Le plan financier met des chiffres sur le projet : combien il faut pour démarrer, ce qui rentre, ce qui sort, et quand. Pour une SRL, un plan financier est d'ailleurs requis à la constitution."}, {"q": "Les charges fixes annuelles sont de 24 000 € et le taux de marge sur coûts variables est de 30 %. Quel chiffre d'affaires faut-il pour atteindre le seuil de rentabilité ?", "choices": ["7 200 €", "31 200 €", "72 000 €", "80 000 €"], "answer": 3, "explain": "Seuil = 24 000 / 0,30 = 80 000 €. En dessous de 80 000 € de CA, la marge ne couvre pas les charges fixes et l'activité perd de l'argent."}, {"q": "Quelle formule approche la valeur d'entreprise (EV) dans une petite ou moyenne entreprise ?", "choices": ["EBITDA × un multiple", "Chiffre d'affaires × nombre de salariés", "Capital social + TVA", "Trésorerie × 10"], "answer": 0, "explain": "On valorise souvent une PME en appliquant un multiple à l'EBITDA (résultat avant intérêts, impôts et amortissements). Le multiple reflète le risque et la qualité de l'entreprise."}, {"q": "Une entreprise dégage un EBITDA de 200 000 € et se négocie sur un multiple de 4. Quelle est sa valeur d'entreprise (EV) ?", "choices": ["50 000 €", "800 000 €", "204 000 €", "2 000 000 €"], "answer": 1, "explain": "EV = EBITDA × multiple = 200 000 × 4 = 800 000 €. C'est la valeur de l'activité elle-même, avant d'ajuster pour la dette et la trésorerie."}, {"q": "Dans quelle fourchette se situent typiquement les multiples d'EBITDA pour une PME ?", "choices": ["Environ 0,1× à 0,5×", "Environ 20× à 30×", "Environ 3× à 7×", "Toujours exactement 10×"], "answer": 2, "explain": "Pour une PME, les multiples d'EBITDA tournent souvent autour de 3× à 7×. Plus l'entreprise est solide et peu risquée, plus le multiple grimpe dans la fourchette."}, {"q": "Lequel de ces facteurs fait MONTER le multiple (donc la valeur) d'une entreprise ?", "choices": ["Un chiffre d'affaires dépendant d'un seul gros client", "Une activité entièrement dans la tête du fondateur", "Un dirigeant indispensable à tout", "Des revenus récurrents, une clientèle diversifiée, une équipe autonome et des processus documentés"], "answer": 3, "explain": "La récurrence, la diversification du portefeuille, l'autonomie de l'équipe et les processus écrits réduisent le risque pour l'acheteur, donc augmentent le multiple et le prix."}, {"q": "Pourquoi une activité de pur service, très dépendante de son fondateur, se revend-elle mal ?", "choices": ["Parce que la valeur part avec le fondateur : sans lui, les clients et le savoir-faire s'évaporent, ce qui effraie l'acheteur", "Parce qu'elle ne fait jamais de bénéfice", "Parce que c'est interdit par la loi", "Parce qu'elle ne paie pas de TVA"], "answer": 0, "explain": "Si tout repose sur une personne, l'acheteur n'achète pas une entreprise mais un emploi risqué. D'où un multiple faible : il n'y a ni récurrence ni actif transmissible solide."}, {"q": "La valeur d'entreprise est de 800 000 €. L'entreprise a 150 000 € de dettes financières et 50 000 € de trésorerie. Quel est le prix des parts (valeur des fonds propres) ?", "choices": ["600 000 €", "700 000 €", "800 000 €", "1 000 000 €"], "answer": 1, "explain": "Prix des parts = EV − dettes + trésorerie = 800 000 − 150 000 + 50 000 = 700 000 €. On achète les parts, donc on retire la dette reprise et on ajoute le cash disponible."}, {"q": "En nom propre (personne physique), comment est globalement taxé le revenu d'un indépendant à titre principal ?", "choices": ["Uniquement par la TVA", "Par l'impôt des sociétés (ISOC)", "Par les cotisations sociales (environ 20,5 % du revenu net) puis par l'impôt des personnes physiques (IPP) progressif", "Il n'est pas taxé"], "answer": 2, "explain": "En personne physique, le revenu net supporte d'abord les cotisations sociales (environ 20,5 %), puis l'IPP progressif. Il n'y a pas d'écran entre l'entreprise et la personne."}, {"q": "En société, comment le dirigeant est-il imposé lorsqu'il sort de l'argent en dividende ?", "choices": ["Rien n'est dû", "Uniquement les cotisations sociales du gérant", "Seule la TVA s'applique", "La société paie d'abord l'impôt des sociétés (ISOC) sur son bénéfice, puis le dividende versé supporte un précompte mobilier"], "answer": 3, "explain": "En société, il y a deux étages : l'ISOC sur le bénéfice, puis le précompte mobilier sur le dividende distribué. La rémunération du dirigeant, elle, suit un autre régime (charge déductible, IPP et cotisations)."}, {"q": "Parmi les « 4 règles pour se payer », laquelle est correcte ?", "choices": ["Séparer les comptes, provisionner pour l'État, se payer un salaire même modeste, et traiter ce salaire comme une vraie ligne de coût", "Tout mélanger sur un seul compte pour simplifier", "Ne jamais se verser de rémunération", "Dépenser la trésorerie dès qu'elle rentre"], "answer": 0, "explain": "Les quatre règles : comptes séparés (pro/perso), provision pour cotisations et impôts, se payer un salaire même petit, et comptabiliser ce salaire comme un coût de l'entreprise, pas comme un reste."}, {"q": "Qu'est-ce que le statut d'étudiant-indépendant en Belgique ?", "choices": ["Un statut réservé aux sociétés cotées", "Un statut permettant à un étudiant d'exercer une activité indépendante avec des cotisations sociales réduites sous conditions (âge, études, revenus)", "Une exonération totale de TVA à vie", "Un statut interdisant toute facturation"], "answer": 1, "explain": "L'étudiant-indépendant permet de tester une activité pendant les études avec un régime de cotisations allégé tant que le revenu reste sous certains plafonds et que les conditions d'études sont remplies."}, {"q": "Qui relève typiquement du statut d'indépendant à titre complémentaire ?", "choices": ["Une personne sans aucune autre activité", "Une société anonyme uniquement", "Une personne qui exerce déjà une activité principale (salarié, par ex.) et développe une activité indépendante en plus", "Un étudiant de moins de 18 ans exclusivement"], "answer": 2, "explain": "Le complémentaire concerne celui qui a déjà une activité principale (salarié à temps plein, pensionné...) et qui exerce en indépendant à côté. Les cotisations dépendent du revenu complémentaire."}, {"q": "Pour un indépendant à titre principal, à combien s'élèvent approximativement les cotisations sociales minimales par trimestre au démarrage ?", "choices": ["Environ 90 €", "Il n'y a aucune cotisation minimale", "Environ 9 000 €", "Environ 900 €"], "answer": 3, "explain": "À titre principal, même avec peu ou pas de revenus, l'indépendant débutant doit une cotisation minimale de l'ordre de 900 € par trimestre. C'est un coût fixe à anticiper absolument."}, {"q": "Un indépendant à titre principal dégage un revenu net de 40 000 € sur l'année. En appliquant un taux de cotisations sociales d'environ 20,5 %, combien doit-il approximativement en cotisations ?", "choices": ["Environ 8 200 €", "Environ 4 100 €", "Environ 2 050 €", "Environ 20 500 €"], "answer": 0, "explain": "Cotisations ≈ 40 000 × 20,5 % ≈ 8 200 €. Et ce n'est pas tout : l'IPP viendra ensuite, d'où l'intérêt de la provision de 35-40 %."}, {"q": "Pourquoi reprendre une PME rentable peut-il être moins risqué que créer de zéro ?", "choices": ["Parce que c'est toujours moins cher", "Parce qu'on rachète une preuve de concept : clients existants, chiffre d'affaires réel, équipe et processus déjà en place", "Parce qu'il n'y a jamais de dette", "Parce qu'on évite de payer la TVA"], "answer": 1, "explain": "Reprendre, c'est acheter une activité qui tourne déjà : le marché, les clients et le modèle sont prouvés. Le risque d'exécution est moindre que de tout bâtir à partir d'une idée non validée."}, {"q": "Pour convaincre un banquier de financer une reprise, quel argument pèse le plus ?", "choices": ["La passion du repreneur, sans chiffres", "La promesse de ne jamais se payer", "Un dossier montrant des cash-flows récurrents, un apport personnel, et une capacité de remboursement démontrée par les résultats de la cible", "L'absence de plan financier"], "answer": 2, "explain": "Le banquier finance une capacité de remboursement : il veut voir des flux de trésorerie récurrents, un apport du repreneur et des comptes de la cible qui prouvent que la dette sera remboursée."}, {"q": "Dans le cas de la « Boulangerie Dubois » (CA 2 M€, EBITDA 250 k€), un client représente 35 % du chiffre d'affaires. Quel est l'enjeu pour le repreneur ?", "choices": ["Aucun, c'est un atout", "Cela supprime la TVA", "Cela augmente automatiquement le prix de vente", "Une forte concentration client : perdre ce client ferait chuter le CA et l'EBITDA, ce qui justifie un multiple plus bas et une clause de garantie"], "answer": 3, "explain": "Dépendre d'un client à 35 % est un risque majeur : s'il part, l'EBITDA s'effondre. L'acheteur en tiendra compte en négociant le multiple à la baisse ou en exigeant des garanties."}, {"q": "Toujours pour la Boulangerie Dubois (EBITDA 250 000 €), avec un multiple de 4, quelle est la valeur d'entreprise ?", "choices": ["1 000 000 €", "500 000 €", "62 500 €", "2 000 000 €"], "answer": 0, "explain": "EV = 250 000 × 4 = 1 000 000 €. Le risque de concentration client (un client à 35 %) pousserait toutefois à négocier un multiple inférieur, donc un prix plus bas."}, {"q": "Quelle est une différence majeure entre exercer en personne physique et en société (SRL) ?", "choices": ["La société ne peut pas facturer", "En société, le patrimoine de l'entreprise est en principe distinct de celui du dirigeant (responsabilité limitée), ce qui n'est pas le cas en personne physique", "La personne physique paie l'ISOC", "La société ne paie jamais d'impôt"], "answer": 1, "explain": "La SRL crée une personne morale distincte : en principe, les créanciers n'atteignent pas le patrimoine privé du dirigeant. En personne physique, biens pro et privés se confondent."}, {"q": "À quoi servent des conditions générales de vente (CGV) bien rédigées ?", "choices": ["À rien, c'est décoratif", "À fixer le taux de TVA national", "À encadrer la relation commerciale : délais et conditions de paiement, intérêts de retard, réserve de propriété, responsabilités, en cas de litige", "À remplacer la facture"], "answer": 2, "explain": "Les CGV protègent l'entreprise : elles définissent les règles du jeu (paiement, pénalités de retard, garanties, responsabilité) et sont décisives en cas de litige ou d'impayé."}, {"q": "Quelle est une caractéristique essentielle de la SRL belge ?", "choices": ["Un capital minimum légal très élevé imposé à la constitution", "Elle est réservée aux activités agricoles", "Elle interdit d'avoir des associés", "Elle n'exige plus de capital minimum légal mais un capital de départ suffisant justifié par un plan financier, avec responsabilité en principe limitée"], "answer": 3, "explain": "Depuis la réforme du droit des sociétés, la SRL n'a plus de capital minimum imposé, mais le fondateur doit prévoir des fonds propres de départ suffisants, justifiés dans un plan financier."}, {"q": "En Belgique, le régime de franchise de TVA pour petites entreprises dispense de porter la TVA en compte en dessous d'un seuil annuel de chiffre d'affaires d'environ :", "choices": ["25 000 €", "2 500 €", "100 000 €", "250 000 €"], "answer": 0, "explain": "Le régime de franchise de TVA s'applique en dessous d'environ 25 000 € de chiffre d'affaires annuel : l'entreprise ne facture pas la TVA, mais ne peut pas non plus la déduire sur ses achats."}, {"q": "Pourquoi la responsabilité limitée d'une société est-elle un argument de protection pour l'entrepreneur ?", "choices": ["Parce qu'elle supprime l'impôt", "Parce qu'en cas de faillite, les pertes sont en principe limitées aux apports, et le patrimoine privé du dirigeant est protégé (sauf fautes de gestion)", "Parce qu'elle garantit des bénéfices", "Parce qu'elle dispense de tenir une comptabilité"], "answer": 1, "explain": "La responsabilité limitée borne le risque financier aux apports : en cas d'échec, le patrimoine privé est en principe à l'abri. Elle tombe toutefois en cas de faute de gestion ou de caution personnelle."}]}}};
